package com.example.backend.service;
import com.example.backend.entity.*; import com.example.backend.repository.*; import org.junit.jupiter.api.Test; import org.springframework.kafka.core.KafkaTemplate; import static org.mockito.Mockito.*;
class KafkaConsumerServiceTest { @Test void repeatedEventIsIgnored(){var posts=mock(ScheduledPostRepository.class);var processed=mock(ProcessedEventRepository.class);var kafka=mock(KafkaTemplate.class);var post=new ScheduledPost();post.setId(12L);when(processed.existsById("12")).thenReturn(true);new KafkaConsumerService(posts,processed,kafka).consumePostEvent(post);verifyNoInteractions(kafka);verify(posts,never()).save(any());} @Test void exhaustedRetryGoesToDlqAfterThreeAttempts(){var posts=mock(ScheduledPostRepository.class);var processed=mock(ProcessedEventRepository.class);var kafka=mock(KafkaTemplate.class);var post=new ScheduledPost();post.setId(13L);post.setContent("[[SIMULATE_FAILURE]]");when(processed.existsById("13")).thenReturn(false);new KafkaConsumerService(posts,processed,kafka).consumePostEvent(post);verify(kafka,times(1)).send("post-topic-dlq","13",post);verify(posts).save(post);verify(processed,never()).save(any());org.assertj.core.api.Assertions.assertThat(post.getAttempts()).isEqualTo(3);org.assertj.core.api.Assertions.assertThat(post.getStatus()).isEqualTo("FAILED");} }
